function i(t){if(t==null)return"—";const e=["B","KiB","MiB","GiB","TiB"];let r=0,n=Number(t);for(;n>=1024&&r<e.length-1;)n/=1024,r++;return`${n>=100||r===0?n.toFixed(0):n.toFixed(1)} ${e[r]}`}function u(t,e=1){return t==null||Number.isNaN(t)?"—":`${(Number(t)*100).toFixed(e)}%`}function o(t){return t==null?"—":t>=1e3?`${(t/1e3).toFixed(2)} s`:`${Number(t).toFixed(0)} ms`}function a(t){if(!t)return"—";const e=new Date(t);if(Number.isNaN(e.getTime()))return t;const r=n=>String(n).padStart(2,"0");return`${e.getFullYear()}-${r(e.getMonth()+1)}-${r(e.getDate())} ${r(e.getHours())}:${r(e.getMinutes())}:${r(e.getSeconds())}`}function f(t){if(!t)return"从未";const e=new Date(t);if(Number.isNaN(e.getTime()))return t;const r=Math.max(0,(Date.now()-e.getTime())/1e3);return r<60?`${Math.floor(r)} 秒前`:r<3600?`${Math.floor(r/60)} 分钟前`:r<86400?`${Math.floor(r/3600)} 小时前`:`${Math.floor(r/86400)} 天前`}function s(t,e=12){return t?t.length>e?t.slice(0,e):t:"—"}export{f as a,i as b,o as m,u as p,s,a as t};
